// Recupere le rapport depuis MinIO
const { filename } = $json;
const axios = require('axios');
const crypto = require('crypto');

const key = 'atlasforge';
const secret = 'atlasforge123';
const bucket = 'atlas-livrables';
const host = 'minio:9000';
const region = 'us-east-1';

const pad = n => String(n).padStart(2,'0');
const now = new Date();
const amzdate = now.getUTCFullYear()+pad(now.getUTCMonth()+1)+pad(now.getUTCDate())+'T'+pad(now.getUTCHours())+pad(now.getUTCMinutes())+pad(now.getUTCSeconds())+'Z';
const dateStamp = amzdate.slice(0,8);
const canonicalUri = '/'+bucket+'/'+filename;
const payloadHash = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';
const canonicalHeaders = 'host:'+host+'\nx-amz-content-sha256:'+payloadHash+'\nx-amz-date:'+amzdate+'\n';
const signedHeaders = 'host;x-amz-content-sha256;x-amz-date';
const canonicalReq = 'GET\n'+canonicalUri+'\n\n'+canonicalHeaders+'\n'+signedHeaders+'\n'+payloadHash;
const credScope = dateStamp+'/'+region+'/s3/aws4_request';
const stringToSign = 'AWS4-HMAC-SHA256\n'+amzdate+'\n'+credScope+'\n'+crypto.createHash('sha256').update(canonicalReq).digest('hex');
function hmac(k,d){return crypto.createHmac('sha256',k).update(d).digest();}
const signingKey = hmac(hmac(hmac(hmac('AWS4'+secret,dateStamp),region),'s3'),'aws4_request');
const signature = crypto.createHmac('sha256',signingKey).update(stringToSign).digest('hex');
const auth = 'AWS4-HMAC-SHA256 Credential='+key+'/'+credScope+', SignedHeaders='+signedHeaders+', Signature='+signature;

let rapportContent = '';
try {
  const resp = await axios({
    method: 'GET',
    url: 'http://'+host+canonicalUri,
    headers: {
      'x-amz-date': amzdate,
      'x-amz-content-sha256': payloadHash,
      'Authorization': auth,
      'Host': host
    }
  });
  rapportContent = resp.data;
} catch(e) {
  rapportContent = '[Rapport indisponible: '+e.message+']';
}

return [{ json: { ...$json, rapportContent } }];

