const { rapportContent, prospectName } = $json;

// Fix: prospectName vient de INIT_OUTREACH — priorite absolue sur le regex
const clientName = prospectName || 'Client';

// Extraire Resume Executif — chercher apres le titre
let apercuGratuit = '';
const resumeIdx = rapportContent.indexOf('## Resume Executif');
if (resumeIdx !== -1) {
  const afterResume = rapportContent.slice(resumeIdx + 20);
  const nextSection = afterResume.search(/^## /m);
  const resumeText = nextSection !== -1 ? afterResume.slice(0, nextSection) : afterResume.slice(0, 1200);
  // Nettoyer et prendre les 2 premiers paragraphes
  const paragraphs = resumeText.split('\n\n').map(p => p.trim()).filter(p => p.length > 60);
  apercuGratuit = paragraphs.slice(0, 2).join('\n\n');
}

// Si pas trouve, essayer Resume Executif sans accent
if (!apercuGratuit) {
  const idx2 = rapportContent.indexOf('Resume Executif');
  if (idx2 !== -1) {
    const after = rapportContent.slice(idx2 + 16);
    const next = after.search(/^## /m);
    const text = next !== -1 ? after.slice(0, next) : after.slice(0, 800);
    const paras = text.split('\n\n').map(p => p.trim()).filter(p => p.length > 60);
    apercuGratuit = paras.slice(0, 2).join('\n\n');
  }
}

// Fallback
if (!apercuGratuit) {
  const lines = rapportContent.split('\n').filter(l => l.length > 80 && !l.startsWith('#') && !l.startsWith('|'));
  apercuGratuit = lines.slice(0, 3).join(' ').slice(0, 600);
}

// Score et niveau
const scoreMatch = rapportContent.match(/Score[:\s]+(\d+)\/100/);
const scoreRisque = scoreMatch ? scoreMatch[1] : '85';

const niveauMatch = rapportContent.match(/CRITIQUE|ELEVE|MOYEN/);
const niveauRisque = niveauMatch ? niveauMatch[0] : 'CRITIQUE';

// Date
const dateMatch = rapportContent.match(/Date audit[^|]*\|([^|]+)\|/);
const dateAudit = dateMatch ? dateMatch[1].trim() : new Date().toLocaleDateString('fr-FR');

// Secteur
const isRH = /rh|paie|salaire|contrat|employe/i.test(rapportContent);
const secteur = isRH ? 'RH / Gestion de Paie' : 'SaaS B2B';

return [{ json: {
  ...$json,
  clientName,
  apercuGratuit,
  scoreRisque,
  niveauRisque,
  dateAudit,
  secteur
}}];

