// LOG dans NocoDB + preparation envoi
// Ce node enregistre le prospect et prepare l email
// L envoi reel sera active quand Gmail sera configure

const { email, clientName, scoreRisque, niveauRisque, filename, stripeLink, prospectEmail } = $json;

// Log dans NocoDB (optionnel - si table OUTREACH_LOG existe)
let nocoStatus = 'SKIPPED';
try {
  const nocoKey = $env.NOCODB_API_KEY || '';
  if (nocoKey) {
    await helpers.httpRequest({
      method: 'POST',
      url: 'http://nocodb:8080/api/v1/db/data/noco/ATLAS/OUTREACH_LOG',
      headers: { 'xc-token': nocoKey, 'Content-Type': 'application/json' },
      body: {
        client: clientName,
        filename: filename,
        score: scoreRisque,
        niveau: niveauRisque,
        email_dest: prospectEmail || 'non_defini',
        stripe_link: stripeLink,
        date_envoi: new Date().toISOString(),
        statut: 'PREPARE'
      },
      json: true
    });
    nocoStatus = 'LOGGED';
  }
} catch(e) {
  nocoStatus = 'NOCO_ERR: '+e.message.slice(0,50);
}

return [{ json: {
  status: 'success',
  version: 'OUTREACH_V2',
  client: clientName,
  email_prepare: {
    to: email.to,
    sujet: email.sujet,
    preview: email.corps.slice(0, 300)+'...',
    html_ready: true
  },
  stripe_link: stripeLink,
  noco_log: nocoStatus,
  next_step: 'Configurer GMAIL_USER + GMAIL_APP_PASSWORD dans n8n Settings pour activer l envoi',
  instructions: {
    gmail: 'myaccount.google.com > Securite > Mots de passe applications > Generer',
    stripe: 'stripe.com > Payment Links > Creer lien 300EUR > Copier URL',
    variables: 'n8n Settings > Variables > GMAIL_USER, GMAIL_APP_PASSWORD, STRIPE_LINK'
  }
}}];

