const nocoKey = '27IYCbJpwko4-PTps7jQpiA90Jklm6WGmPZ_2rlv';
const urlBase = 'http://nocodb:8080/api/v1/db/data/noco/p10jh0dkphkze90/mb6dwmaubxp21jp';

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  try {
    // 🔍 On vérifie si l'email existe
    const check = await helpers.httpRequest({
      method: 'GET', url: urlBase, qs: { where: `(contact_email,eq,${data.email})` },
      headers: { 'xc-token': nocoKey }, json: true
    });

    if (!check.list || check.list.length === 0) {
      // 🚀 Nouveau ! On injecte
      await helpers.httpRequest({
        method: 'POST', url: urlBase, headers: { 'xc-token': nocoKey, 'Content-Type': 'application/json' },
        body: { nom_societe: data.company, contact_email: data.email, status: 'A SCANNER' },
        json: true
      });
      results.push({ email: data.email, action: 'ADDED' });
    } else {
      results.push({ email: data.email, action: 'SKIPPED' });
    }
  } catch (e) { results.push({ email: data.email, error: e.message }); }
}
return results;

