const { apolloKey } = $json;

let people = [];

try {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: 'https://api.apollo.io/v1/mixed_people/search',
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'no-cache',
      'X-Api-Key': apolloKey
    },
    body: {
      page: 1,
      per_page: 50,
      person_titles: ['DSI', 'RSSI', 'CTO', 'DRH', 'Directeur Informatique'],
      organization_locations: ['France'],
      organization_num_employees_ranges: ['20,500'],
      contact_email_status: ['verified', 'likely to engage']
    },
    json: true
  });

  console.log('Apollo status:', JSON.stringify(res).slice(0, 300));
  people = res.people || [];
  console.log('Apollo retourne:', people.length, 'contacts');

} catch(e) {
  console.log('Erreur Apollo:', e.message);
  people = [];
}

// Si Apollo vide → fallback liste manuelle
if (people.length === 0) {
  console.log('Apollo vide — utilisation du fallback manuel');

  // REMPLACE CES LIGNES PAR TES NOUVEAUX PROSPECTS
  const fallback = [
    { company: 'Exemple SAS', email: 'dsi@exemple.fr', score: 75, secteur: 'SaaS', url_site: 'https://exemple.fr' }
  ];

  return fallback.map(f => ({ json: f }));
}

// Normaliser données Apollo
function scoreLead(p) {
  let s = 50;
  const titre = (p.title || '').toLowerCase();
  if (/rssi|sécurité|security/.test(titre)) s += 30;
  else if (/dsi|cto|technique/.test(titre)) s += 20;
  else if (/drh|rh/.test(titre)) s += 15;
  const emp = p.organization?.estimated_num_employees || 0;
  if (emp >= 100 && emp <= 500) s += 15;
  else if (emp >= 50) s += 10;
  if (p.email_status === 'verified') s += 10;
  return Math.min(s, 100);
}

return people
  .filter(p => p.email && p.organization)
  .map(p => ({
    json: {
      company: p.organization.name || '',
      email: (p.email || '').toLowerCase().trim(),
      url_site: p.organization.website_url || '',
      secteur: p.organization.industry || 'Tech / SaaS',
      score: scoreLead(p)
    }
  }));

