const crypto = require('crypto');

const filename  = $json.forge?.filename || 'atlas-livrable.md';
const livrable  = $json.operator?.livrable || '';
const body      = Buffer.from(livrable, 'utf-8');

const accessKey = 'atlasforge';
const secretKey = 'atlasforge123';
const bucket    = 'atlas-livrables';
const hostSign  = 'minio';        // HOST pour la SIGNATURE — sans port
const hostUrl   = 'minio:9000';   // HOST pour l URL — avec port
const region    = 'us-east-1';
const service   = 's3';

const now = new Date();
const pad = n => String(n).padStart(2,'0');
const amzdate   = now.getUTCFullYear()+pad(now.getUTCMonth()+1)+pad(now.getUTCDate())+'T'+pad(now.getUTCHours())+pad(now.getUTCMinutes())+pad(now.getUTCSeconds())+'Z';
const dateStamp = amzdate.slice(0,8);

const payloadHash      = crypto.createHash('sha256').update(body).digest('hex');
const canonicalUri     = '/'+bucket+'/'+filename;
const canonicalHeaders = 'host:'+hostSign+'\nx-amz-content-sha256:'+payloadHash+'\nx-amz-date:'+amzdate+'\n';
const signedHeaders    = 'host;x-amz-content-sha256;x-amz-date';
const canonicalReq     = 'PUT\n'+canonicalUri+'\n\n'+canonicalHeaders+'\n'+signedHeaders+'\n'+payloadHash;
const credScope        = dateStamp+'/'+region+'/'+service+'/aws4_request';
const stringToSign     = 'AWS4-HMAC-SHA256\n'+amzdate+'\n'+credScope+'\n'+crypto.createHash('sha256').update(canonicalReq).digest('hex');

function hmac(key,data){return crypto.createHmac('sha256',key).update(data).digest();}
const signingKey = hmac(hmac(hmac(hmac('AWS4'+secretKey,dateStamp),region),service),'aws4_request');
const signature  = crypto.createHmac('sha256',signingKey).update(stringToSign).digest('hex');
const authHeader = 'AWS4-HMAC-SHA256 Credential='+accessKey+'/'+credScope+', SignedHeaders='+signedHeaders+', Signature='+signature;

let forgeSaved = false;
let forgeUrl   = '';
try{
  await helpers.httpRequest({
    method:'PUT',
    url:'http://'+hostUrl+'/'+bucket+'/'+filename,
    headers:{
      'Content-Type':'text/plain; charset=utf-8',
      'Host':hostSign,
      'x-amz-date':amzdate,
      'x-amz-content-sha256':payloadHash,
      'Authorization':authHeader
    },
    body:body
  });
  forgeSaved = true;
  forgeUrl   = 'http://localhost:9100/browser/atlas-livrables/'+filename;
}catch(e){
  forgeUrl = '[FORGE ERR] '+e.message;
}

return [{
  json:{
    ...$json,
    forge:{saved:forgeSaved,filename:filename,bucket:bucket,url:forgeUrl}
  }
}];

