const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');

const filename = $json.forge?.filename || 'atlas-livrable.md';
const livrable  = $json.operator?.livrable || '';
const body      = Buffer.from(livrable, 'utf-8');

const client = new S3Client({
  endpoint: 'http://minio:9000',
  region: 'us-east-1',
  credentials: {
    accessKeyId: 'atlasforge',
    secretAccessKey: 'atlasforge123'
  },
  forcePathStyle: true
});

let forgeSaved = false;
let forgeUrl   = '';

try {
  await client.send(new PutObjectCommand({
    Bucket: 'atlas-livrables',
    Key: filename,
    Body: body,
    ContentType: 'text/markdown; charset=utf-8',
    ContentLength: body.length
  }));
  forgeSaved = true;
  forgeUrl = 'http://localhost:9100/browser/atlas-livrables/' + filename;
} catch(e) {
  forgeUrl = '[FORGE ERR] ' + e.message;
}

return [{
  json: {
    ...$json,
    forge: { saved: forgeSaved, filename, bucket: 'atlas-livrables', url: forgeUrl }
  }
}];

