const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function callGroq(sys,prompt,key){
  try{const r=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:{model:'llama-3.1-8b-instant',max_tokens:780,temperature:0.65,messages:[{role:'system',content:sys},{role:'user',content:prompt}]},json:true});return r&&r.choices&&r.choices[0]?r.choices[0].message.content:'Indisponible';}catch(e){
  if(e.message&&e.message.includes('429')){await sleep(13000);try{const r2=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:{model:'mixtral-8x7b-32768',max_tokens:680,messages:[{role:'system',content:sys},{role:'user',content:prompt}]},json:true});return r2&&r2.choices&&r2.choices[0]?r2.choices[0].message.content:'[429 T3]';}catch(e2){await sleep(11000);try{const r3=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:{model:'llama-3.1-8b-instant',max_tokens:600,temperature:0.6,messages:[{role:'system',content:sys},{role:'user',content:prompt}]},json:true});return r3&&r3.choices&&r3.choices[0]?r3.choices[0].message.content:'[429 T3 triple]';}catch(e3){return '[429 T3 final]';}}}
  return '[ERR T3] '+e.message;}}
const t1s=tour1.map(function(p){return '['+p.agent+']: '+p.position.slice(0,260);}).join('

');
const t2s=tour2.map(function(c){return '['+c.agent+' T2]: '+c.critique.slice(0,210);}).join('

');
const agentIds=Object.keys(agentSys);
const tour3=[];
for(let i=0;i<agentIds.length;i++){
