  if(e.message&&e.message.includes('429')){await sleep(11000);try{const r2=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:{model:'mixtral-8x7b-32768',max_tokens:640,messages:[{role:'system',content:sys},{role:'user',content:prompt}]},json:true});return r2&&r2.choices&&r2.choices[0]?r2.choices[0].message.content:'[429]';}catch(e2){await sleep(9000);try{const r3=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:{model:'llama-3.1-8b-instant',max_tokens:560,messages:[{role:'system',content:sys},{role:'user',content:prompt}]},json:true});return r3&&r3.choices&&r3.choices[0]?r3.choices[0].message.content:'[429 T2]';}catch(e3){return '[429 T2 final]';}}}
  return '[ERR T2] '+e.message;}}
const agentIds=Object.keys(agentSys);
const tour2=[];
for(let i=0;i<agentIds.length;i++){
  const id=agentIds[i];
  const myPos=tour1.find(function(p){return p.agent===id;});
  const others=tour1.filter(function(p){return p.agent!==id;}).map(function(p){return '['+p.agent+']: '+p.position.slice(0,280);}).join('\n\n');
  const r=await callGroq(agentSys[id],'CLIENT "'+clientName+'" — MISSION: "'+question+'"\n\nTA POSITION T1:\n'+(myPos?myPos.position.slice(0,340):'')+'\n\nPOSITIONS ADVERSES:\n'+others+'\n\nTU ES '+id+'. CONTRE-ATTAQUE: demolit chaque agent par son nom avec un fait reel chiffre. Aligne-toi avec UN seul agent. Reformule encore plus tranche avec chiffres. 300 mots max.',groqKey);
  tour2.push({agent:id,critique:r});
  if(i<agentIds.length-1) await sleep(5000);
}
return [{json:{question,clientName,startTime,groqKey,webContext,tour1,tour2,agentSys,anthropicKey,operatorMode,wantsClaude}}];

