const {question,clientName,tour1,tour2,tour3,synthese_collegiale,startTime,groqKey,anthropicKey,operatorMode,wantsClaude}=$json;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));

const q=question.toLowerCase();
const isAudit = /audit|securit|stride|rssi|pentest|vulnerabilit|faille|conformit|rgpd|iso 27|cyber/.test(q);
const isCode  = !isAudit && /\bcode\b|script|python|javascript|nodejs|\bapi\b|backend|frontend|\bapp\b|saas|bot|scraper|automat|cron|developp|creer|fastapi|flask/.test(q);
const isDoc   = !isAudit && /rapport|document|presentation|pitch|business plan|cahier|spec/.test(q);
const isN8N   = /n8n|workflow|webhook|pipeline/.test(q);

const debateSummary='CLIENT: "'+clientName+'"\nMISSION: "'+question+'"\nINSIGHTS ATLAS: '+synthese_collegiale.slice(0,700);
const debateFull=tour1.map(function(p){return '['+p.agent+']: '+p.position.slice(0,200);}).join('\n')+'\n'+tour3.map(function(f){return '['+f.agent+' T3]: '+f.finale.slice(0,200);}).join('\n');

const today=new Date().toLocaleDateString('fr-FR');
let opType,opPrompt;

if(isAudit){
  opType='AUDIT_SECURITE';
  opPrompt=debateSummary+'\n\nDEBAT EXPERTS:\n'+debateFull+'\n\n'+
'Genere un RAPPORT AUDIT SECURITE PRESTIGE vendable 300 euros. Structure OBLIGATOIRE:\n\n'+
'# RAPPORT D AUDIT DE SECURITE STRIDE\n'+
'**CONFIDENTIEL — USAGE EXCLUSIF '+clientName+'**\n\n'+
'## Page de couverture\n'+
'| Champ | Valeur |\n|-------|--------|\n'+
'| Client | '+clientName+' |\n'+
'| Type | SaaS B2B |\n'+
'| Date audit | '+today+' |\n'+
'| Auditeur | ATLAS Security Council |\n'+
'| Classification | CONFIDENTIEL |\n'+
'| Niveau criticite | 🔴 CRITIQUE |\n'+
'| Validite | 90 jours |\n\n'+
'## Resume Executif — Ce que votre DG doit savoir\n'+
'[3 paragraphes PERCUTANTS pour un DRH non-technique:\n'+
'1. La menace sectorielle actuelle sur les SaaS RH (cite Cegedim/Kronos/PayFit)\n'+
'2. Impact business : decris la perte operationnelle potentielle et les risques de conformite sans affirmer de chiffres absolus\n'+
'3. Les 3 actions de mitigation recommandees pour J+1]\n\n'+
'## Score de Risque Global\n'+
'**Score estimé: XX/100** — Niveau: [CRITIQUE/ELEVE/MOYEN]\n'+
'[Justification basee sur la surface dexposition publique et comparaison sectorielle]\n\n'+
'## Analyse STRIDE Complete\n'+
'### S — Spoofing (Usurpation d identite)\n'+
'**Vecteur potentiel**: [description attack sur SaaS RH]\n'+
'**Probabilite**: [X]/5\n'+
'**Cas sectoriel similaire**: [incident reel avec nom entreprise+annee+cout constate]\n'+
'**Correction recommandée**: [librairie==version] - snippet 3 lignes\n'+
'### T — Tampering (Falsification donnees)\n[meme structure — incident Kronos obligatoire]\n'+
'### R — Repudiation (Deni d action)\n[meme structure]\n'+
'### I — Information Disclosure (Fuite donnees)\n[meme structure — incident Cegedim obligatoire]\n'+
'### D — Denial of Service (Interruption service)\n[meme structure]\n'+
'### E — Elevation of Privilege (Escalade privileges)\n[meme structure — PeopleSoft CVE obligatoire]\n\n'+
'## Matrice Risques Estimée\n'+
'| Menace | Proba/5 | Impact/5 | Score | Priorite | Action |\n'+
'|--------|---------|----------|-------|----------|--------|\n'+
'| Spoofing | 4 | 5 | 20 | CRITIQUE | 24h |\n'+
'| Tampering | 3 | 4 | 12 | ELEVE | 1sem |\n'+
'| Repudiation | 2 | 3 | 6 | MOYEN | 2sem |\n'+
'| Info Disclosure | 4 | 5 | 20 | CRITIQUE | 24h |\n'+
'| DoS | 3 | 4 | 12 | ELEVE | 1sem |\n'+
'| EoP | 4 | 5 | 20 | CRITIQUE | 24h |\n\n'+
'## Conformite RGPD (Vues Externes)\n'+
'| Article | Obligation | Statut Estimé | Risque Max |\n'+
'|---------|-----------|--------|------------|\n'+
'| Art.5 | Licéité traitement | [A VERIFIER] | Sanctions sectorielles |\n'+
'| Art.25 | Privacy by design | [SOUS RÉSERVE] | Interruption service |\n'+
'| Art.32 | Securite traitement | [POINT DE VIGILANCE] | Sanction CNIL |\n'+
'| Art.33 | Notification violation | [NON DÉTECTÉ] | 10M€ |\n\n'+
'## Plan Remediation\n'+
'### Actions prioritaires (Estimations J+1 a J+3)\n'+
'1. [ACTION CONCRETE avec outil exact+responsable+indicateur succes]\n'+
'### Budget Securite Sectoriel Recommande\n'+
'[5 lignes avec vrais outils et prix du marche]\n\n'+
'## Conclusion\n'+
'[Synthese expert + urgence de securisation + disponibilite equipe ATLAS]\n\n'+
'---\n'+
'*Rapport analytique généré par ATLAS Security Council le '+today+' pour '+clientName+'*\n'+
'*Usage consultatif — Ne remplace pas un test d intrusion intrusif*';
}

// 🚩 AJOUT DES REGLES JURIDIQUES ET PRESTIGE DANS LES SYSTEM PROMPTS
const legalDisclaimer = " REGLE JURIDIQUE : Ne jamais affirmer de pertes chiffrées absolues concernant le prospect. Utilise des termes comme 'impact estimé basé sur des cas sectoriels', 'risque opérationnel majeur' ou 'préjudice potentiel'. Ton style doit être celui d'un consultant senior en stratégie (Big Four style) : sobre, factuel et précis. Pas de sensationnalisme.";

const sysOpGroq='Tu es OPERATOR ATLAS V19 PRESTIGE — consultant expert cybersécurité (15 ans).' + legalDisclaimer + ' REGLE TECHNIQUE: ZERO placeholder, ZERO société fictive, vrais incidents cités, outils exacts. Tu commences DIRECTEMENT par le livrable.';
const sysOpClaude='Tu es OPERATOR ATLAS V19 PRESTIGE — consultant senior en architecture critique SaaS B2B.' + legalDisclaimer + ' REGLE TECHNIQUE: code hexagonal, type hints strict, ZERO placeholder. Tu commences DIRECTEMENT par le livrable.';

let livrable='Livrable indisponible';
let usedModel='unknown';

if(operatorMode==='claude'&&anthropicKey){
  try{
    const r=await helpers.httpRequest({method:'POST',url:'https://api.anthropic.com/v1/messages',headers:{'x-api-key':anthropicKey,'anthropic-version':'2023-06-01','Content-Type':'application/json'},body:{model:'claude-3-5-sonnet-20240620',max_tokens:4500,system:sysOpClaude,messages:[{role:'user',content:opPrompt}]},json:true});
    if(r&&r.content&&r.content[0]&&r.content[0].text){livrable=r.content[0].text;usedModel='claude-3-5-sonnet';}
  }catch(e){usedModel='groq-fallback';}
}

if(usedModel==='unknown'||usedModel==='groq-fallback'){
  try{
    const r=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+groqKey,'Content-Type':'application/json'},body:{model:'llama-3.3-70b-versatile',max_tokens:3500,temperature:0.1,messages:[{role:'system',content:sysOpGroq},{role:'user',content:opPrompt}]},json:true});
    if(r&&r.choices&&r.choices[0]){livrable=r.choices[0].message.content;usedModel='groq-llama-3.3-70b';}
  }catch(e){
    if(e.message&&e.message.includes('429')){await sleep(30000);try{const r2=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+groqKey,'Content-Type':'application/json'},body:{model:'llama-3.3-70b-versatile',max_tokens:3000,temperature:0.1,messages:[{role:'system',content:sysOpGroq},{role:'user',content:opPrompt}]},json:true});if(r2&&r2.choices&&r2.choices[0]){livrable=r2.choices[0].message.content;usedModel='groq-70b-retry';}}catch(e2){livrable='[OPERATOR 429]';}}
    else{livrable='[OPERATOR ERR] '+e.message;}
  }
}

const ts=new Date().toISOString().replace(/[:.]/g,'-').slice(0,19);
const ext=opType==='CODE'?'py':opType==='N8N_WORKFLOW'?'json':'md';
const forgeFilename='atlas-'+ts+'-'+clientName.replace(/[^a-z0-9]/gi,'_').toLowerCase()+'-'+opType.toLowerCase()+'.'+ext;

const ok1=tour1.filter(function(a){return a.position&&!a.position.startsWith('[');}).length;
const ok2=tour2.filter(function(a){return a.critique&&!a.critique.startsWith('[');}).length;
const ok3=tour3.filter(function(a){return a.finale&&!a.finale.startsWith('[');}).length;

const fileBuffer=Buffer.from(livrable,'utf-8');
return [{
  binary:{data:{data:fileBuffer.toString('base64'),mimeType:'text/markdown',fileName:forgeFilename}},
  json:{
    status:'success',version:'19.0-PRESTIGE',
    debate:{
      tour1:tour1.map(function(a){return {agent:a.agent,position:a.position};}),
      tour2:tour2.map(function(a){return {agent:a.agent,critique:a.critique};}),
      tour3:tour3.map(function(a){return {agent:a.agent,finale:a.finale};}),
    },
    synthese_collegiale,
    operator:{type:opType,model:usedModel,livrable,client:clientName},
    forge:{filename:forgeFilename,bucket:'atlas-livrables'},
    participants:['STRATEGE','BATISSEUR','INGENIEUR','DISRUPTEUR','GARDIEN','ANALYSTE'],
    stats:{tours:3,agents:6,agents_ok:Math.min(Math.round((ok1+ok2+ok3)/3),6),operator_mode:operatorMode,used_claude:usedModel.includes('claude'),responseTime:Math.round((Date.now()-startTime)/1000)}
  }
}];

