const crypto = require('crypto');

const filename = $json.forge?.filename || 'atlas-livrable.md';
const livrable = $json.operator?.livrable || '';
const body = Buffer.from(livrable, 'utf-8');

const key    = 'atlasforge';
const secret = 'atlasforge123';
const bucket = 'atlas-livrables';
const host   = 'minio:9000';
const region = 'us-east-1';

const pad = n => String(n).padStart(2,'0');
const now = new Date();
const amzdate = now.getUTCFullYear()+pad(now.getUTCMonth()+1)+pad(now.getUTCDate())+'T'+pad(now.getUTCHours())+pad(now.getUTCMinutes())+pad(now.getUTCSeconds())+'Z';
const dateStamp = amzdate.slice(0,8);
const payloadHash = crypto.createHash('sha256').update(body).digest('hex');
const canonicalUri = '/'+bucket+'/'+filename;
const canonicalHeaders = 'host:'+host+'\nx-amz-content-sha256:'+payloadHash+'\nx-amz-date:'+amzdate+'\n';
const signedHeaders = 'host;x-amz-content-sha256;x-amz-date';
const canonicalReq = 'PUT\n'+canonicalUri+'\n\n'+canonicalHeaders+'\n'+signedHeaders+'\n'+payloadHash;
const credScope = dateStamp+'/'+region+'/s3/aws4_request';
const stringToSign = 'AWS4-HMAC-SHA256\n'+amzdate+'\n'+credScope+'\n'+crypto.createHash('sha256').update(canonicalReq).digest('hex');
function hmac(k,d){return crypto.createHmac('sha256',k).update(d).digest();}
const signingKey = hmac(hmac(hmac(hmac('AWS4'+secret,dateStamp),region),'s3'),'aws4_request');
const signature = crypto.createHmac('sha256',signingKey).update(stringToSign).digest('hex');
const auth = 'AWS4-HMAC-SHA256 Credential='+key+'/'+credScope+', SignedHeaders='+signedHeaders+', Signature='+signature;

let forgeSaved = false;
let forgeUrl = '';

try {
  await axios({
    method: 'PUT',
    url: 'http://'+host+canonicalUri,
    data: body,
    headers: {
      'Content-Type': 'text/plain; charset=utf-8',
      'Content-Length': body.length,
      'x-amz-date': amzdate,
      'x-amz-content-sha256': payloadHash,
      'Authorization': auth,
      'Host': host
    },
    maxBodyLength: Infinity,
    maxContentLength: Infinity
  });
  forgeSaved = true;
  forgeUrl = 'http://localhost:9100/browser/atlas-livrables/'+filename;
} catch(e) {
  forgeUrl = '[FORGE ERR] '+(e.response ? e.response.status+' '+JSON.stringify(e.response.data).slice(0,150) : e.message);
}

// On ne renvoie QUE du JSON propre, sans les résidus binaires des nodes précédents
return [{ json: { 
    status: 'success',
    version: '19.0-FIXED',
    debate: $json.debate,
    synthese_collegiale: $json.synthese_collegiale,
    operator: $json.operator,
    forge: { 
      saved: forgeSaved, 
      filename, 
      bucket: 'atlas-livrables', 
      url: forgeUrl,
      size: body.length
    },
    stats: $json.stats
}}];

