const nocoKey = '27IYCbJpwko4-PTps7jQpiA90Jklm6WGmPZ_2rlv';
const nocoTableUrl = 'http://nocodb:8080/api/v1/db/data/noco/p10jh0dkphkze90/mb6dwmaubxp21jp';

const forge = $json.forge || {};
const fileSize = forge.size || 0;
const webhookBody = $node["WEBHOOK"].json.body || {};
let rId = webhookBody.noco_record_id || null;
const pEmail = webhookBody.prospect_email || '';

// Fallback lookup ID par email
if (!rId && pEmail) {
  try {
    const lookup = await helpers.httpRequest({
      method: 'GET', url: nocoTableUrl,
      qs: { where: `(contact_email,eq,${pEmail})`, limit: 1 },
      headers: { 'xc-token': nocoKey }, json: true
    });
    if (lookup.list && lookup.list.length > 0) rId = lookup.list[0].Id;
  } catch(e) {}
}

let statusToSet = (fileSize > 1000) ? 'MAIL ENVOYÉ' : 'ECHEC_IA_429';

if (fileSize > 1000 && pEmail) {
  try {
    await helpers.httpRequest({
      method: 'POST',
      url: 'http://localhost:5678/webhook/forge-outreach',
      headers: { 'Content-Type': 'application/json' },
      body: {
        filename: forge.filename,
        email: pEmail,
        prospect_name: webhookBody.prospect_name || webhookBody.company_name
      },
      json: true
    });
  } catch (e) {
    statusToSet = 'ERREUR WORKFLOW';
  }
}

// MISE À JOUR NOCODB
if (rId) {
  try {
    await helpers.httpRequest({
      method: 'PATCH',
      url: `${nocoTableUrl}/${rId}`,
      headers: { 'xc-token': nocoKey, 'Content-Type': 'application/json' },
      body: { 
        status: statusToSet,
        score_impact: String(fileSize),
        lead_magnet_url: forge.url || "",
        last_scan_date: new Date().toISOString().split('T')[0]
      },
      json: true
    });
  } catch(e) {}
}

return [{ json: { status: statusToSet, size: fileSize } }];

