const ATLAS_URL = 'http://localhost:5678/webhook/atlas-debate';

const item = $input.first();
if (!item) return [];

const data = item.json;
if (!data.noco_record_id) return [];

try {
  await helpers.httpRequest({
    method: 'POST',
    url: ATLAS_URL,
    headers: { 'Content-Type': 'application/json' },
    body: {
      company_name: data.company,
      prospect_email: data.email,
      prospect_name: data.company,
      noco_record_id: data.noco_record_id
    },
    json: true,
    timeout: 30000
  });
} catch(e) {
  console.log('Signal ATLAS envoye pour:', data.company);
}

console.log('ATLAS lance pour:', data.company);
return [{ json: { status: 'ATLAS_LANCE', company: data.company } }];

